SELECT COUNT(DISTINCT a.hadm_id) AS num_admissions FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN transfers t ON a.subject_id = t.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id WHERE p.gender = 'M' AND p.anchor_age = 95 AND p.anchor_year >= 2019 AND p.anchor_year <= 2021 AND (d.icd_code = '585.6' OR d.icd_code = 'N18.6') AND t.eventtype = 'transfer';